70	<script>
71	  import router from '@system.router'
72	  import prompt from '@system.prompt'
73	  import storage from '@system.storage'
74	
75	  export default {
76	    private: {
77	      favorites: [],
78	      loading: true
79	    },
80	
81	    // onShow 每次回到本页都刷新，保证详情页收藏/取消后列表同步
82	    onShow() {
83	      this.refreshFavorites()
84	    },
85	
86	    // 读取收藏列表：兼容旧数据里纯数字元素，统一转成对象格式（只读不写回，storage 原格式保持不变）
87	    refreshFavorites() {
88	      var self = this
89	      storage.get({
90	        key: 'favorite_list',
91	        success: function(data) {
92	          var list = []
93	          try {
94	            list = JSON.parse(data) || []
95	          } catch(e) {
96	            list = []
97	          }
98	          var normalized = list.map(function(item) {
99	            if (typeof item === 'number') {
100	              return { id: item, title: '事件 #' + item, yearDisplay: '', region: '' }
101	            }
102	            return {
103	              id: item.id || 0,
104	              title: item.title || '未知事件',
105	              yearDisplay: item.yearDisplay || '',
106	              region: item.region || ''
107	            }
108	          })
109	          self.favorites = normalized
110	          self.loading = false
111	        },
112	        fail: function() {
113	          self.favorites = []
114	          self.loading = false
115	        }
116	      })
117	    },
118	
119	    // 点击条目进入详情页（与 result.ux/index.ux 一致：先写 global.selectedEventId 再跳转）
120	    gotoDetail(id) {
121	      if (id === undefined || id === null) return
122	      if (this.$app.$def.isNavigating) return
123	      global.selectedEventId = id
124	      if (typeof global.addRuntimeLog === 'function') {
125	        global.addRuntimeLog('从收藏打开详情: ID=' + id, 'info')
126	      }
127	      router.push({ uri: '/pages/detail', params: { id: id } })
128	    },
129	
130	    // 移除收藏：按 id 从数组剔除并写回 storage（self 写法避免回调内 this 依赖）
131	    removeFavorite(id) {
132	      var self = this
133	      var idx = -1
134	      for (var i = 0; i < this.favorites.length; i++) {
135	        if (this.favorites[i].id === id) {
136	          idx = i
137	          break
138	        }
139	      }
140	      if (idx === -1) return
141	      var newFavorites = []
142	      for (var j = 0; j < this.favorites.length; j++) {
143	        if (j !== idx) {
144	          newFavorites.push(this.favorites[j])
145	        }
146	      }
147	      self.favorites = newFavorites
148	      storage.set({
149	        key: 'favorite_list',
150	        value: JSON.stringify(newFavorites),
151	        success: function() {
152	          prompt.showToast({ message: '已移除收藏', duration: 500 })
153	          global.addRuntimeLog && global.addRuntimeLog('移除收藏: ID=' + id, 'info')
154	        },
155	        fail: function() {
156	          prompt.showToast({ message: '移除收藏失败', duration: 500 })
157	        }
158	      })
159	    },
160	
161	    // 右滑返回
162	    onSwipe(eve) { if (eve.direction === 'right') { router.back() } },
163	
164	    goBack() { router.back() }
165	  }
166	</script>
