444	
445	          // 检查是否已经在内存中
446	          if (engine.mapData && engine.mapData[mapId]) {
447	            resolve(true)
448	            return
449	          }
450	
451	          // 从 storage 读取缓存
452	          var storageModule = require('@system.storage')
453	          var cacheKey = engine._getMapCacheKey ? engine._getMapCacheKey(mapId) : ('search_engine_map_v1_' + mapId)
454	
455	          storageModule.get({
456	            key: cacheKey,
457	            success: function(data) {
458	              try {
459	                var mapData = JSON.parse(data)
460	                if (!engine.mapData) engine.mapData = {}
461	                engine.mapData[mapId] = mapData
462	                if (typeof global.addRuntimeLog === 'function') {
463	                  global.addRuntimeLog('[detail] 从缓存加载 Map ' + mapId + ' 成功', 'success')
464	                }
465	                resolve(true)
466	              } catch(e) {
467	                resolve(false)
468	              }
469	            },
470	            fail: function() {
471	              resolve(false)
472	            }
473	          })
474	        } catch(e) {
475	          resolve(false)
476	        }
477	      })
478	    },
