580	    _getRegionName(regionId) {
581	      var regionList = global.searchEngine ? global.searchEngine.getRegionList() : []
582	      var regionMap = {
583	        'asia': '亚洲',
584	        'europe': '欧洲',
585	        'africa': '非洲',
586	        'north_america': '北美洲',
587	        'south_america': '南美洲',
588	        'other': '其他'
589	      }
590	      var tag = (regionList && regionList[regionId]) ? regionList[regionId] : '未知'
591	      return regionMap[tag] || tag
592	    },
593	
594	    // ============================================================
595	    // 收藏功能
596	    // ============================================================
597	    checkFavoriteStatus(id) {
598	      var self = this
599	      storage.get({
600	        key: 'favorite_list',
601	        success: function(data) {
602	          try {
603	            var favorites = JSON.parse(data) || []
604	            var found = false
605	            for (var i = 0; i < favorites.length; i++) {
606	              var item = favorites[i]
607	              var itemId = (typeof item === 'number') ? item : (item.id || 0)
608	              if (itemId === id) {
609	                found = true
610	                break
611	              }
612	            }
613	            self.isFavorited = found
614	          } catch(e) {
615	            self.isFavorited = false
616	          }
617	        },
618	        fail: function() {
619	          self.isFavorited = false
620	        }
621	      })
622	    },
623	
624	    toggleFavorite() {
625	      var self = this
626	
627	      if (this.eventId === undefined || this.eventId === null) {
628	        prompt.showToast({ message: '错误：事件ID无效', duration: 1000 })
629	        return
630	      }
631	
632	      var currentId = this.eventId
633	      var wasFavorited = this.isFavorited
634	
635	      var favoriteItem = {
636	        id: currentId,
637	        yearDisplay: this.yearDisplay || '未知',
638	        title: this.detailTitle || (this.keywordList && this.keywordList.length > 0 ? this.keywordList[0] : '未知事件'),
639	        region: this.displayRegion || '未知'
640	      }
641	
642	      storage.get({
643	        key: 'favorite_list',
644	        success: function(data) {
645	          var favorites = []
646	          try {
647	            favorites = JSON.parse(data) || []
648	          } catch(e) {
649	            favorites = []
650	          }
651	
652	          if (wasFavorited) {
653	            var newFavorites = []
654	            for (var i = 0; i < favorites.length; i++) {
655	              var item = favorites[i]
656	              var itemId = (typeof item === 'number') ? item : (item.id || 0)
657	              if (itemId !== currentId) {
658	                newFavorites.push(item)
659	              }
660	            }
661	            storage.set({
662	              key: 'favorite_list',
663	              value: JSON.stringify(newFavorites),
664	              success: function() {
665	                self.isFavorited = false
666	                prompt.showToast({ message: '已取消收藏', duration: 500 })
667	                if (typeof global.addRuntimeLog === 'function') {
668	                  global.addRuntimeLog('取消收藏成功: ID=' + currentId, 'info')
669	                }
670	              },
671	              fail: function() {
672	                prompt.showToast({ message: '取消收藏失败', duration: 500 })
673	              }
674	            })
675	          } else {
676	            var exists = false
677	            for (var i = 0; i < favorites.length; i++) {
678	              var item = favorites[i]
679	              var itemId = (typeof item === 'number') ? item : (item.id || 0)
680	              if (itemId === currentId) {
681	                exists = true
682	                break
683	              }
684	            }
685	            if (!exists) {
686	              favorites.push(favoriteItem)
687	            }
688	            storage.set({
689	              key: 'favorite_list',
690	              value: JSON.stringify(favorites),
691	              success: function() {
692	                self.isFavorited = true
693	                prompt.showToast({ message: '已添加收藏', duration: 500 })
694	                if (typeof global.addRuntimeLog === 'function') {
695	                  global.addRuntimeLog('添加收藏成功: ID=' + currentId, 'info')
696	                }
697	              },
698	              fail: function() {
699	                prompt.showToast({ message: '添加收藏失败', duration: 500 })
700	              }
701	            })
702	          }
703	        },
704	        fail: function() {
705	          if (!wasFavorited) {
706	            var favorites = [favoriteItem]
707	            storage.set({
708	              key: 'favorite_list',
709	              value: JSON.stringify(favorites),
710	              success: function() {
711	                self.isFavorited = true
712	                prompt.showToast({ message: '已添加收藏', duration: 500 })
713	              }
714	            })
715	          }
716	        }
717	      })
718	    },
719	
