const fs = require('fs')
const files = [
  'src/pages/detail/detail.ux',
  'src/pages/index/index.ux'
]
let failed = false
for (const f of files) {
  const s = fs.readFileSync(f, 'utf8')
  const m = s.match(/<script>([\s\S]*)<\/script>/)
  if (!m) { console.log(f + ': NO SCRIPT'); failed = true; continue }
  const out = f.replace(/\//g, '_').replace(/\.ux$/, '.mjs')
  fs.writeFileSync('_chk_' + out, m[1])
  console.log(f + ' extracted -> _chk_' + out)
}
process.exit(failed ? 1 : 0)

